import { Command } from "commander";

import { invoke, type Implementation } from "@gooi/exchange";
import { artifact } from "@gooi/kernel/evidence";
import { commands } from "./commands.js";

async function run(edge: Implementation, input: unknown, output = "json") {
  try {
    const { artifact: result } = await invoke(edge, artifact(edge.operation.input, input));

    if (output === "text" && typeof result.value !== "string") throw new Error("Expected text output");

    console.log(output === "text" ? result.value : JSON.stringify(result.value, null, 2));
  } catch(error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  }
}

const program = new Command("nooq").description("nooq's tasks and room, composed from gooi's apps");
const taskCommands = program.command("task").description("Track nooq's tasks as Markdown files in its tasks/ folder");

taskCommands.command("list").description("List open and done tasks, and any files that can't be read").action((options) => run(commands.task.commands.list, { ...options }));
taskCommands.command("add").description("Add a task as a Markdown file, <name>.md, in the task folder").requiredOption("--title <title>", "One-line title").option("--name <name>", "File name; made from the title when left out").option("--notes <notes>", "Notes written below the title").action((options) => run(commands.task.commands.add, { ...options }));
taskCommands.command("finish").description("Mark a task done, changing only its header").requiredOption("--name <name>", "Task name, or a prefix that matches one task").action((options) => run(commands.task.commands.finish, { ...options }));

const roomCommands = program.command("room").description("Talk nooq's work through with agents; @claude or @omlx mentions one, @room mentions all");

roomCommands.command("say").description("Post to a room as the owner; agents you mention with @name answer").requiredOption("--room <room>", "Room name: lowercase letters, digits, dots, dashes and underscores").requiredOption("--text <text>", "Your message; @name mentions an agent and @room mentions everyone").action((options) => run(commands.room.commands.say.edge, { ...options }, "text"));
roomCommands.command("show").description("Show a room's messages").requiredOption("--room <room>", "Room name: lowercase letters, digits, dots, dashes and underscores").action((options) => run(commands.room.commands.show.edge, { ...options }, "text"));
await program.parseAsync();
